#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 5;
    int *cells = malloc(n * sizeof(int));
    if (cells == NULL) {
        printf("out of memory\n");
        return 1;
    }
    for (int i = 0; i < n; i++) cells[i] = i * i;

    int total = 0;
    for (int i = 0; i < n; i++) total += cells[i];
    printf("total %d\n", total);

    free(cells);
    return 0;
}

