#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int capacity = 2, count = 0, value;
    int *log = malloc(capacity * sizeof(int));
    if (log == NULL) return 1;

    while (scanf("%d", &value) == 1 && value != 0) {
        if (count == capacity) {
            capacity *= 2;
            int *bigger = realloc(log, capacity * sizeof(int));
            if (bigger == NULL) {
                free(log);
                return 1;
            }
            log = bigger;
        }
        log[count++] = value;
    }

    printf("%d readings, room for %d\n", count, capacity);
    printf("last: %d\n", log[count - 1]);
    free(log);
    return 0;
}

