#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) exit(1);
    n->value = value;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    head = push(head, 1);
    head = push(head, 2);
    head = push(head, 3);

    for (Node *p = head; p != NULL; p = p->next) printf("%d -> ", p->value);
    printf("NULL\n");

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

